// Fork golden vectors for the Hanko payloads (the codec's exact bytes and hashes).
//
// Derived from og's tests/fixtures/onchain-hanko-golden.ts (same VECTOR values, same bytes for every payload the fork left
// alone). og's own copy cannot be imported: tests/ has a package.json without a module type, so the loader Hardhat runs
// suites with links it as CommonJS and its named exports are not found. Settlement, dispute and batch differ from og's by
// design and were recomputed with ethers.AbiCoder / solidityPacked, not with the Solidity codec under test:
//   settlement, dispute  abi.encode(kind, chainId, depository, accountKey, ondeltaEpoch, nonce, ...)   (C1)
//   batch                packed(XLN_DEPOSITORY_HANKO_V2, chainId, depository, entityId, encodedBatch, nonce)   (C2)
// The same recomputation over og's shapes (no epoch, V1, no entity) reproduces og's three original hashes byte for byte.

export const ONCHAIN_HANKO_VECTOR = {
  chainId: 8453,
  depositoryAddress: '0x1111111111111111111111111111111111111111',
  entityProviderAddress: '0x6666666666666666666666666666666666666666',
  boardEpoch: 11,
  towerAddress: '0x2222222222222222222222222222222222222222',
  leftEntity: `0x${'11'.repeat(32)}`,
  rightEntity: `0x${'22'.repeat(32)}`,
  watchSeed: `0x${'33'.repeat(32)}`,
  proofBodyHash: `0x${'44'.repeat(32)}`,
  starterArgumentsHash: `0x${'55'.repeat(32)}`,
  // The fork binds the Account's ondelta epoch into the settlement and dispute payloads (C1) and the acting entity into
  // the batch payload (C2, domain XLN_DEPOSITORY_HANKO_V2).
  ondeltaEpoch: 5,
  batchEntity: `0x${'aa'.repeat(32)}`,
  accountNonce: 7,
  batchNonce: 8,
  encodedBatch: '0x1234abcd',
  diffs: [{ tokenId: 9, leftDiff: -7n, rightDiff: 2n, collateralDiff: 5n, ondeltaDiff: -3n }],
  forgiveDebtsInTokenIds: [12],
  watchtower: { finalNonce: 9, lastResortWindowSeconds: 16, appointmentSequence: 3 },
  entityTransfer: { entityNumber: 42, tokenId: 9, amount: 123, actionNonce: 4 },
  releaseControlShares: {
    entityNumber: 42,
    controlAmount: 100,
    dividendAmount: 200,
    purpose: 'Series A',
    actionNonce: 5,
  },
  cancelEntityProviderAction: {
    entityNumber: 42,
    actionNonce: 6,
    cancelledActionHash: `0x${'77'.repeat(32)}`,
    cancelledActionKind: 0,
  },
  boardProposal: {
    entityId: `0x${'11'.repeat(32)}`,
    newBoardHash: `0x${'88'.repeat(32)}`,
    authority: 1,
    actionNonce: 7,
  },
  boardProposalCancel: {
    entityId: `0x${'11'.repeat(32)}`,
    proposedBoardHash: `0x${'88'.repeat(32)}`,
    proposedBy: 3,
    cancelledBy: 2,
    actionNonce: 7,
  },
} as const;

